/**
 * Binary object storage for uploaded files (DIP: services depend on this,
 * not on the disk or a cloud SDK). Keys are generated by the server only.
 */
export interface FileStorage {
  put(key: string, data: Buffer): Promise<void>;
  /** Null when the key is unknown or not a valid server-generated key. */
  get(key: string): Promise<Buffer | null>;
  /** Idempotent. */
  remove(key: string): Promise<void>;
}
